"""Tree-based pairwise diff minimization."""

from __future__ import annotations

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.tree import NodeType
from reduction.tree_utils import delete_paths, node_at_path, walk_entries

from ppr.diff_utils import token_diff


class MinTdiff:
    """Reduce each side when doing so shrinks the token-level difference."""

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    def reduce(
        self,
        seed_source: str,
        variant_source: str,
        seed_tester: PropertyTester,
        variant_tester: PropertyTester,
    ) -> tuple[str, str]:
        current_seed = seed_source
        current_variant = variant_source

        while True:
            progress = False

            updated_seed = self._reduce_side(
                source=current_seed,
                other_source=current_variant,
                tester=seed_tester,
            )
            if updated_seed != current_seed:
                current_seed = updated_seed
                progress = True

            updated_variant = self._reduce_side(
                source=current_variant,
                other_source=current_seed,
                tester=variant_tester,
            )
            if updated_variant != current_variant:
                current_variant = updated_variant
                progress = True

            if not progress:
                return current_seed, current_variant

    def _reduce_side(
        self,
        source: str,
        other_source: str,
        tester: PropertyTester,
    ) -> str:
        current_source = source

        while True:
            tree = self.parser.parse(current_source)
            entries = self._deletable_entries(tree)
            current_diff = self._diff_size(current_source, other_source)
            progress = False

            for entry in entries:
                candidate_tree = delete_paths(tree, [entry.path])
                if candidate_tree is None:
                    continue
                candidate_source = candidate_tree.to_source()
                if self._diff_size(candidate_source, other_source) >= current_diff:
                    continue
                if tester.test(candidate_source):
                    current_source = candidate_source
                    progress = True
                    break

            if not progress:
                return current_source

    def _deletable_entries(self, tree) -> list:
        candidates = []
        blocked_prefixes: set[tuple[int, ...]] = set()

        for entry in walk_entries(tree):
            if not entry.path:
                continue
            if any(entry.path[: len(prefix)] == prefix for prefix in blocked_prefixes):
                continue
            if self._is_whole_node_deletable(tree, entry.path):
                candidates.append(entry)
                blocked_prefixes.add(entry.path)

        candidates.sort(key=lambda entry: (-entry.node.token_count(), len(entry.path)))
        return candidates

    def _is_whole_node_deletable(self, tree, path: tuple[int, ...]) -> bool:
        parent = node_at_path(tree, path[:-1])
        node = node_at_path(tree, path)
        if parent is None or node is None:
            return False

        if parent.node_type == NodeType.KLEENE_STAR:
            return True
        if parent.node_type == NodeType.KLEENE_PLUS:
            return len(parent.children) > 1
        if parent.node_type == NodeType.REGULAR and node.node_type in (
            NodeType.OPTIONAL,
            NodeType.KLEENE_STAR,
        ):
            return True
        return False

    def _diff_size(self, left_source: str, right_source: str) -> int:
        left_only, right_only = token_diff(left_source, right_source)
        return len(left_only) + len(right_only)

